const nomorDiizinkan = [
  'REDACTED_PHONE_NUMBER',
  '6289678438317@c.us',
  '178322847871231@lid'
  // tambah nomor/lid lain di sini, pisahkan dengan koma
];

const body = $input.first().json.body;
const pengirim = body?.payload?.from || '';
const hasMedia = body?.payload?.hasMedia || false;
const media = body?.payload?.media || null;

const diizinkan = nomorDiizinkan.includes(pengirim);

return [{ json: { diizinkan, pengirim, pesanMasuk: (body?.payload?.body || ''), hasMedia, media } }];

const media = $json.media;
const mimetype = media?.mimetype || '';
const validExcelCsv = mimetype.includes('csv') || mimetype.includes('spreadsheet') || mimetype.includes('excel');
const adaFileValid = $json.hasMedia && validExcelCsv;

return [{ json: { ...$json, adaFileValid } }];

const pesanMasuk = ($json.pesanMasuk || '').toLowerCase();

let jenisPertanyaan = 'tidak_dikenali';

if (pesanMasuk.includes('minggu')) {
  jenisPertanyaan = 'ringkasan_minggu';
} else if (pesanMasuk.includes('penjualan') || pesanMasuk.includes('revenue') || pesanMasuk.includes('omset')) {
  jenisPertanyaan = 'revenue_hari_ini';
} else if (pesanMasuk.includes('produk terlaris') || pesanMasuk.includes('laris')) {
  jenisPertanyaan = 'top_produk';
} else if (pesanMasuk.includes('order') || pesanMasuk.includes('transaksi')) {
  jenisPertanyaan = 'jumlah_orders';
}

return [{ json: { jenisPertanyaan, pengirim: $json.pengirim } }];

const hasil = $input.first().json;
const jenisPertanyaan = $('Deteksi Jenis Pertanyaan').first().json.jenisPertanyaan;
const formatRupiah = (angka) => 'Rp' + angka.toLocaleString('id-ID');
const LINK_DASHBOARD = 'http://192.168.0.103:3001';

let balasan = '';

switch (jenisPertanyaan) {
  case 'ringkasan_minggu':
    const daftarMinggu = hasil.top_produk.map((p, i) => `${i + 1}. ${p.produk} (${p.qty_terjual}x)`).join('\n');
    balasan = `📅 *Ringkasan Minggu Ini*\n${hasil.periode}\n\n💰 Revenue: *${formatRupiah(hasil.total_revenue)}*\n🧾 Orders: ${hasil.total_orders}\n📈 AOV: ${formatRupiah(hasil.aov)}\n\n🏆 *Produk Terlaris:*\n${daftarMinggu}`;
    break;
  case 'revenue_hari_ini':
    const topHarian = hasil.top_produk.map((p, i) => `${i + 1}. ${p.produk} (${p.qty_terjual} terjual)`).join('\n');
    balasan = `📊 *Laporan Penjualan Hari Ini*\n${hasil.tanggal}\n\n💰 Revenue: ${formatRupiah(hasil.total_revenue)}\n🧾 Orders: ${hasil.total_orders}\n📈 AOV: ${formatRupiah(hasil.aov)}\n\n🏆 *Produk Terlaris:*\n${topHarian}`;
    break;
  case 'top_produk':
    const daftar = hasil.top_produk.map((p, i) => `${i + 1}. ${p.produk} — ${p.qty_terjual}x`).join('\n');
    balasan = `🏆 *Produk Terlaris*\n${hasil.tanggal}\n\n${daftar}`;
    break;
  case 'jumlah_orders':
    balasan = `🧾 *Transaksi ${hasil.tanggal}*\n\nJumlah: ${hasil.total_orders} transaksi\nRata-rata belanja: ${formatRupiah(hasil.aov)}`;
    break;
  default:
    balasan = '🤔 Maaf, saya belum paham pertanyaannya.\n\nCoba tanya soal *"penjualan hari ini"*, *"produk terlaris"*, *"minggu ini"*, atau kirim file CSV/Excel untuk update data.';
}

if (jenisPertanyaan !== 'tidak_dikenali') {
  balasan += `\n\n➖➖➖➖➖\n📱 Buka dashboard lengkap:\n${LINK_DASHBOARD}`;
}

return [{ json: { balasan, pengirim: $('Deteksi Jenis Pertanyaan').first().json.pengirim } }];

const hasil = $input.first().json;
const pengirim = $('Cek Nomor Diizinkan').first().json.pengirim;

let balasan = '';
if (hasil.error) {
  balasan = `\u274c *Upload gagal*\n\n${hasil.error}`;
} else {
  balasan = `\u2705 *Data berhasil diproses!*\n\n${hasil.active_count} transaksi masuk laporan.`;
  if (hasil.needs_review_count > 0) {
    balasan += `\n\u26a0\ufe0f ${hasil.needs_review_count} transaksi butuh review sebelum masuk laporan (cek dashboard).`;
  }
  if (hasil.duplicate_flag_count > 0) {
    balasan += `\n\ud83d\udd0e ${hasil.duplicate_flag_count} kemungkinan duplikat ditemukan (cek dashboard).`;
  }
  balasan += `\n\nKetik "penjualan hari ini" untuk lihat laporan terbaru.`;
}

return [{ json: { balasan, pengirim } }];
